import type { Account, Analytics, BalanceAdjustment, BudgetOccurrence, BudgetSchedule, Contribution, Expense, GoalContribution, PlannedSpending, Transaction, Transfer } from '../types'

export const expenseCategories = ['Food', 'Transportation', 'Bills', 'Shopping', 'Entertainment', 'Health', 'Education', 'Investment', 'Others']
export const savingTypes = ['Emergency Fund', 'Travel Fund', 'Investment Fund', 'House Fund', 'Others']

/** Formats values consistently in Philippine pesos. */
export function formatCurrency(amount: number, compact = false) {
  return new Intl.NumberFormat('en-PH', {
    style: 'currency',
    currency: 'PHP',
    notation: compact ? 'compact' : 'standard',
    maximumFractionDigits: compact ? 1 : 2,
  }).format(Number.isFinite(amount) ? amount : 0)
}

/** Returns a local calendar date as an ISO date string. */
export function localDate(date = new Date()) {
  return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 10)
}

/** Formats the current local wall-clock time without converting the calendar day through UTC. */
export function localDateTime(date = new Date()) {
  return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 19)
}

/** Returns a month key for filtering local date strings. */
export function monthKey(date: string) {
  return date.slice(0, 7)
}

/** Derives an account balance exclusively from its opening amount and ledger activity. */
export function accountBalance(account: Account, transactions: Transaction[], transfers: Transfer[], _contributions: Contribution[], adjustments: BalanceAdjustment[]) {
  const transactionDelta = transactions.reduce((sum, entry) => {
    if (entry.accountId !== account.id) return sum
    if (entry.type === 'income') return sum + entry.amount
    if (entry.type === 'expense') return sum - entry.amount
    return sum
  }, 0)
  const transferDelta = transfers.reduce((sum, transfer) => sum + (transfer.destinationAccountId === account.id ? transfer.amount : transfer.sourceAccountId === account.id ? -transfer.amount : 0), 0)
  const adjustmentDelta = adjustments.reduce((sum, adjustment) => sum + (adjustment.accountId === account.id ? adjustment.amount : 0), 0)
  return account.openingBalance + transactionDelta + transferDelta + adjustmentDelta
}

/** Sums active included accounts without treating internal savings allocations as spending. */
export function totalMoney(accounts: Account[], transactions: Transaction[], transfers: Transfer[], contributions: Contribution[], adjustments: BalanceAdjustment[]) {
  return accounts.filter((account) => account.includeInTotal && !account.archived).reduce((sum, account) => sum + accountBalance(account, transactions, transfers, contributions, adjustments), 0)
}

/** Returns the amount currently allocated to savings records. */
export function totalSavings(transactions: Transaction[]) {
  return transactions.filter((entry) => entry.type === 'saving').reduce((sum, entry) => sum + entry.amount, 0)
}

/** Totals savings moved from available funds; legacy saving entries are treated as transfers. */
export function allocatedSavings(transactions: Transaction[]) {
  return transactions.filter((entry) => entry.type === 'saving' && entry.mode !== 'opening').reduce((sum, entry) => sum + entry.amount, 0)
}

/** Calculates discretionary money after savings allocations and active reserved plans. */
export function availableToSpend(total: number, transactions: Transaction[], plans: PlannedSpending[], today = localDate(), goalContributions: GoalContribution[] = [], budgetSchedules: BudgetSchedule[] = [], budgetOccurrences: BudgetOccurrence[] = []) {
  const savings = totalSavings(transactions)
  const plannedReservations = plans.filter((plan) => plan.reserveMoney && (plan.date >= today || plan.status === 'Due') && ['Upcoming', 'Active', 'Due'].includes(plan.status)).reduce((sum, plan) => sum + plan.maximumAmount, 0)
  const goalReservations = goalContributions.filter((entry) => entry.type === 'reserve').reduce((sum, entry) => sum + entry.amount, 0)
  const schedulesById = new Map(budgetSchedules.map((schedule) => [schedule.id, schedule]))
  const scheduleReservations = budgetOccurrences.filter((occurrence) => (occurrence.date >= today || occurrence.status === 'due') && ['scheduled', 'due'].includes(occurrence.status) && schedulesById.get(occurrence.budgetScheduleId)?.status === 'active' && schedulesById.get(occurrence.budgetScheduleId)?.reservationMode === 'reserve').reduce((sum, occurrence) => sum + occurrence.plannedAmount, 0)
  return total - savings - plannedReservations - goalReservations - scheduleReservations
}

/** Derives an account's usable balance after its linked savings and active reservations. */
export function accountAvailableBalance(account: Account, transactions: Transaction[], transfers: Transfer[], contributions: Contribution[], adjustments: BalanceAdjustment[], plans: PlannedSpending[], goalContributions: GoalContribution[], budgetSchedules: BudgetSchedule[] = [], budgetOccurrences: BudgetOccurrence[] = [], today = localDate()) {
  const physical = accountBalance(account, transactions, transfers, contributions, adjustments)
  const savings = transactions.filter((entry) => entry.type === 'saving' && entry.accountId === account.id).reduce((sum, entry) => sum + entry.amount, 0)
  const plannedReservations = plans.filter((plan) => plan.accountId === account.id && plan.reserveMoney && (plan.date >= today || plan.status === 'Due') && ['Upcoming', 'Active', 'Due'].includes(plan.status)).reduce((sum, plan) => sum + plan.maximumAmount, 0)
  const goalReservations = goalContributions.filter((entry) => entry.accountId === account.id && entry.type === 'reserve').reduce((sum, entry) => sum + entry.amount, 0)
  const schedulesById = new Map(budgetSchedules.map((schedule) => [schedule.id, schedule]))
  const scheduleReservations = budgetOccurrences.filter((occurrence) => (occurrence.date >= today || occurrence.status === 'due') && ['scheduled', 'due'].includes(occurrence.status) && schedulesById.get(occurrence.budgetScheduleId)?.status === 'active' && schedulesById.get(occurrence.budgetScheduleId)?.sourceAccountId === account.id && schedulesById.get(occurrence.budgetScheduleId)?.reservationMode === 'reserve').reduce((sum, occurrence) => sum + occurrence.plannedAmount, 0)
  return physical - savings - plannedReservations - goalReservations - scheduleReservations
}

/** Formats an ISO date into a short readable date. */
export function formatDate(date: string, options: Intl.DateTimeFormatOptions = { month: 'short', day: 'numeric' }) {
  return new Intl.DateTimeFormat('en-PH', options).format(new Date(`${date}T12:00:00`))
}

/** Calculates average and peak-spending metrics from expense records. */
export function calculateAnalytics(transactions: Transaction[], contributions: Contribution[] = []): Analytics {
  const expenses: Pick<Expense, 'date' | 'amount' | 'category'>[] = [...transactions.filter((entry): entry is Expense => entry.type === 'expense' && !entry.contributionId).map(({ date, amount, category }) => ({ date, amount, category })), ...contributions.filter((entry) => entry.status === 'paid' && entry.includeInExpenseAnalytics).map((entry) => ({ date: entry.contributionDate ?? entry.date, amount: entry.amount, category: entry.category }))]
  const dayTotals = new Map<string, number>()
  const categoryTotals = new Map<string, number>()
  const monthTotals = new Map<string, number>()
  for (const expense of expenses) {
    dayTotals.set(expense.date, (dayTotals.get(expense.date) ?? 0) + expense.amount)
    categoryTotals.set(expense.category, (categoryTotals.get(expense.category) ?? 0) + expense.amount)
    monthTotals.set(monthKey(expense.date), (monthTotals.get(monthKey(expense.date)) ?? 0) + expense.amount)
  }
  const totalExpense = expenses.reduce((sum, entry) => sum + entry.amount, 0)
  const totalIncome = transactions.filter((entry) => entry.type === 'income').reduce((sum, entry) => sum + entry.amount, 0)
  const days = new Set(expenses.map((entry) => entry.date)).size
  const mostExpensive = [...dayTotals.entries()].sort((a, b) => b[1] - a[1])[0]
  return {
    averageDailyExpense: days ? totalExpense / days : 0,
    averageMonthlyExpense: monthTotals.size ? totalExpense / monthTotals.size : 0,
    savingsRate: totalIncome ? Math.max(0, (totalIncome - totalExpense) / totalIncome * 100) : 0,
    mostExpensiveDay: mostExpensive ? { date: mostExpensive[0], amount: mostExpensive[1] } : null,
    biggestCategories: [...categoryTotals.entries()].map(([category, amount]) => ({ category, amount })).sort((a, b) => b.amount - a.amount),
  }
}

/** Builds the last six calendar months of chart-ready income and expense totals. */
export function buildMonthlyTrend(transactions: Transaction[], anchor = new Date(), contributions: Contribution[] = []) {
  return Array.from({ length: 6 }, (_, index) => {
    const date = new Date(anchor.getFullYear(), anchor.getMonth() - 5 + index, 1)
    const month = localDate(date).slice(0, 7)
    const values = transactions.filter((entry) => monthKey(entry.date) === month)
    return {
      month: new Intl.DateTimeFormat('en', { month: 'short' }).format(date),
      income: values.filter((entry) => entry.type === 'income').reduce((sum, entry) => sum + entry.amount, 0),
      expenses: values.filter((entry) => entry.type === 'expense' && !entry.contributionId).reduce((sum, entry) => sum + entry.amount, 0) + contributions.filter((entry) => entry.status === 'paid' && entry.includeInExpenseAnalytics && monthKey(entry.contributionDate ?? entry.date) === month).reduce((sum, entry) => sum + entry.amount, 0),
      savings: values.filter((entry) => entry.type === 'saving' && entry.mode !== 'opening').reduce((sum, entry) => sum + entry.amount, 0),
      contributions: contributions.filter((entry) => entry.status === 'paid' && monthKey(entry.contributionDate ?? entry.date) === month).reduce((sum, entry) => sum + entry.amount, 0),
    }
  })
}